@code {
    private static readonly string[] StepLabels = ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    private int _currentStep = 1;
    private bool _loading;
    private bool _submitted;
    private int _applicationId;
    private string? _errorMessage;

    // Step 1
    private string _fullName = string.Empty;
    private string _email = string.Empty;
    private string _phone = string.Empty;
    private string _address = string.Empty;

    // Step 2
    private List<WorkEntryModel> _workEntries = [new()];

    // Step 3
    private List<RefModel> _references = [new(), new()];

    // Step 4
    private string _coverLetter = string.Empty;

    // ─── Navigation ───
    private void GoToStep(int step)
    {
        if (step < _currentStep && !_submitted)
        {
            _errorMessage = null;
            _currentStep = step;
        }
    }

    private void PrevStep()
    {
        _errorMessage = null;
        if (_currentStep > 1) _currentStep--;
    }

    private async Task NextStep()
    {
        _errorMessage = null;

        if (!ValidateCurrentStep())
            return;

        if (_currentStep == 1)
        {
            _loading = true;
            try
            {
                var emailValid = await ApplicationService.ValidateEmailAsync(_email);
                if (!emailValid)
                {
                    _errorMessage = "Please enter a valid email address.";
                    return;
                }
            }
            finally { _loading = false; }
        }

        _currentStep++;
    }

    private bool ValidateCurrentStep()
    {
        switch (_currentStep)
        {
            case 1:
                if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email)
                    || string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
                {
                    _errorMessage = "All personal information fields are required.";
                    return false;
                }
                break;
            case 2:
                foreach (var e in _workEntries)
                {
                    if (string.IsNullOrWhiteSpace(e.Company) || string.IsNullOrWhiteSpace(e.Title) || e.StartDate is null)
                    {
                        _errorMessage = "Company, job title, and start date are required for each position.";
                        return false;
                    }
                }
                break;
            case 3:
                foreach (var r in _references)
                {
                    if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                        || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
                    {
                        _errorMessage = "All fields are required for each reference.";
                        return false;
                    }
                }
                break;
            case 4:
                if (string.IsNullOrWhiteSpace(_coverLetter))
                {
                    _errorMessage = "Please write a cover letter.";
                    return false;
                }
                break;
        }
        return true;
    }

    // ─── Work Entries ───
    private void AddWorkEntry() => _workEntries.Add(new());
    private void RemoveWorkEntry(int idx) => _workEntries.RemoveAt(idx);
    private void UpdateWork(int idx, WorkEntryModel updated) => _workEntries[idx] = updated;

    // ─── References ───
    private void AddReference() { if (_references.Count < 3) _references.Add(new()); }
    private void RemoveReference(int idx) => _references.RemoveAt(idx);
    private void UpdateRef(int idx, RefModel updated) => _references[idx] = updated;

    // ─── Submit ───
    private async Task SubmitApplication()
    {
        _loading = true;
        _errorMessage = null;
        try
        {
            var application = new JobApplication(
                new PersonalInfo(_fullName, _email, _phone, _address),
                new WorkHistory(_workEntries.Select(e =>
                    new WorkEntry(e.Company, e.Title, e.StartDate ?? DateTime.MinValue, e.IsCurrent ? null : e.EndDate, e.Description)).ToList()),
                _references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                _coverLetter
            );
            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch (Exception ex)
        {
            _errorMessage = $"Submission failed: {ex.Message}";
        }
        finally { _loading = false; }
    }

    // ─── Helpers ───
    private string StepBadgeClass(int step) =>
        step < _currentStep ? "btn-success text-white"
        : step == _currentStep ? "btn-primary text-white"
        : "btn-light text-muted border";

    // Mutable view-models for the form
    private record WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime? StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }

    private record RefModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }
}

